content:
Below is a focused Pulumi TypeScript implementation of a `ComponentResource` wrapping the S3 assets bucket, PostgreSQL RDS instance, and service-account IAM identity. It supports independently deployed `dev` and `prod` stacks through Pulumi stack configuration.

## Project structure

```text
.
├── package.json
├── tsconfig.json
├── Pulumi.yaml
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── index.ts
└── components
    └── applicationData.ts
```

## `components/applicationData.ts`

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface ApplicationDataArgs {
    environment: "dev" | "prod";

    /**
     * Subnets used by the RDS DB subnet group. Normally these are private
     * subnets spanning at least two availability zones.
     */
    databaseSubnetIds: pulumi.Input<pulumi.Input<string>[]>;

    /**
     * Security groups controlling access to PostgreSQL.
     * They should only allow port 5432 from the application/EKS nodes.
     */
    databaseSecurityGroupIds: pulumi.Input<pulumi.Input<string>[]>;

    databaseName: pulumi.Input<string>;
    databaseUsername: pulumi.Input<string>;

    /**
     * Must be supplied with Config.requireSecret().
     */
    databasePassword: pulumi.Input<string>;

    serviceAccount: {
        namespace: pulumi.Input<string>;
        name: pulumi.Input<string>;

        /**
         * ARN of the EKS IAM OIDC provider.
         */
        oidcProviderArn: pulumi.Input<string>;

        /**
         * Issuer URL from the EKS cluster, for example:
         * https://oidc.eks.us-east-1.amazonaws.com/id/ABC123
         */
        oidcIssuerUrl: pulumi.Input<string>;
    };

    /**
     * Required in prod to create the us-west-2 replication bucket.
     */
    replicationProvider?: aws.Provider;

    tags?: pulumi.Input<Record<string, pulumi.Input<string>>>;
}

export class ApplicationData extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly bucketName: pulumi.Output<string>;
    public readonly bucketArn: pulumi.Output<string>;

    public readonly replicationBucket?: aws.s3.BucketV2;

    public readonly database: aws.rds.Instance;
    public readonly databaseEndpoint: pulumi.Output<string>;
    public readonly databaseConnectionString: pulumi.Output<string>;

    public readonly serviceAccountRole: aws.iam.Role;
    public readonly serviceAccountRoleArn: pulumi.Output<string>;

    /**
     * Dev-only programmatic identity.
     */
    public readonly developmentUser?: aws.iam.User;
    public readonly developmentAccessKey?: aws.iam.AccessKey;
    public readonly developmentAccessKeyId?: pulumi.Output<string>;
    public readonly developmentSecretAccessKey?: pulumi.Output<string>;

    constructor(
        name: string,
        args: ApplicationDataArgs,
        opts?: pulumi.ComponentResourceOptions,
    ) {
        super("example:components:ApplicationData", name, {}, opts);

        const childOptions: pulumi.CustomResourceOptions = {
            parent: this,
        };

        const tags = pulumi.output(args.tags).apply(input => ({
            ...(input ?? {}),
            Environment: args.environment,
            Component: name,
            ManagedBy: "Pulumi",
        }));

        /*
         * Primary application assets bucket.
         */
        this.bucket = new aws.s3.BucketV2(
            `${name}-assets`,
            {
                forceDestroy: args.environment === "dev",
                tags,
            },
            childOptions,
        );

        const bucketVersioning = new aws.s3.BucketVersioningV2(
            `${name}-assets-versioning`,
            {
                bucket: this.bucket.id,
                versioningConfiguration: {
                    status: "Enabled",
                },
            },
            childOptions,
        );

        new aws.s3.BucketServerSideEncryptionConfigurationV2(
            `${name}-assets-encryption`,
            {
                bucket: this.bucket.id,
                rules: [{
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: "AES256",
                    },
                    bucketKeyEnabled: true,
                }],
            },
            childOptions,
        );

        new aws.s3.BucketPublicAccessBlock(
            `${name}-assets-public-access-block`,
            {
                bucket: this.bucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
            },
            childOptions,
        );

        /*
         * Prod cross-region replication destination in us-west-2.
         */
        if (args.environment === "prod") {
            if (!args.replicationProvider) {
                throw new pulumi.ResourceError(
                    "replicationProvider is required for the prod stack",
                    this,
                );
            }

            const replicationOptions: pulumi.CustomResourceOptions = {
                parent: this,
                provider: args.replicationProvider,
            };

            this.replicationBucket = new aws.s3.BucketV2(
                `${name}-assets-replica`,
                {
                    forceDestroy: false,
                    tags,
                },
                replicationOptions,
            );

            const replicaVersioning = new aws.s3.BucketVersioningV2(
                `${name}-assets-replica-versioning`,
                {
                    bucket: this.replicationBucket.id,
                    versioningConfiguration: {
                        status: "Enabled",
                    },
                },
                replicationOptions,
            );

            new aws.s3.BucketServerSideEncryptionConfigurationV2(
                `${name}-assets-replica-encryption`,
                {
                    bucket: this.replicationBucket.id,
                    rules: [{
                        applyServerSideEncryptionByDefault: {
                            sseAlgorithm: "AES256",
                        },
                        bucketKeyEnabled: true,
                    }],
                },
                replicationOptions,
            );

            new aws.s3.BucketPublicAccessBlock(
                `${name}-assets-replica-public-access-block`,
                {
                    bucket: this.replicationBucket.id,
                    blockPublicAcls: true,
                    blockPublicPolicy: true,
                    ignorePublicAcls: true,
                    restrictPublicBuckets: true,
                },
                replicationOptions,
            );

            const replicationRole = new aws.iam.Role(
                `${name}-s3-replication-role`,
                {
                    assumeRolePolicy: aws.iam.getPolicyDocumentOutput({
                        statements: [{
                            effect: "Allow",
                            principals: [{
                                type: "Service",
                                identifiers: ["s3.amazonaws.com"],
                            }],
                            actions: ["sts:AssumeRole"],
                        }],
                    }).json,
                    tags,
                },
                childOptions,
            );

            new aws.iam.RolePolicy(
                `${name}-s3-replication-policy`,
                {
                    role: replicationRole.id,
                    policy: aws.iam.getPolicyDocumentOutput({
                        statements: [
                            {
                                effect: "Allow",
                                actions: [
                                    "s3:GetReplicationConfiguration",
                                    "s3:ListBucket",
                                ],
                                resources: [this.bucket.arn],
                            },
                            {
                                effect: "Allow",
                                actions: [
                                    "s3:GetObjectVersion",
                                    "s3:GetObjectVersionAcl",
                                    "s3:GetObjectVersionForReplication",
                                    "s3:GetObjectVersionTagging",
                                ],
                                resources: [
                                    pulumi.interpolate`${this.bucket.arn}/*`,
                                ],
                            },
                            {
                                effect: "Allow",
                                actions: [
                                    "s3:ReplicateDelete",
                                    "s3:ReplicateObject",
                                    "s3:ReplicateTags",
                                ],
                                resources: [
                                    pulumi.interpolate`${this.replicationBucket.arn}/*`,
                                ],
                            },
                        ],
                    }).json,
                },
                childOptions,
            );

            new aws.s3.BucketReplicationConfig(
                `${name}-assets-replication`,
                {
                    bucket: this.bucket.id,
                    role: replicationRole.arn,
                    rules: [{
                        id: "replicate-to-us-west-2",
                        status: "Enabled",
                        filter: {
                            prefix: "",
                        },
                        destination: {
                            bucket: this.replicationBucket.arn,
                            storageClass: "STANDARD",
                        },
                        deleteMarkerReplication: {
                            status: "Enabled",
                        },
                    }],
                },
                {
                    parent: this,
                    dependsOn: [bucketVersioning, replicaVersioning],
                },
            );
        }

        /*
         * PostgreSQL RDS instance.
         */
        const dbSubnetGroup = new aws.rds.SubnetGroup(
            `${name}-db-subnets`,
            {
                subnetIds: args.databaseSubnetIds,
                tags,
            },
            childOptions,
        );

        const dbParameterGroup = new aws.rds.ParameterGroup(
            `${name}-postgres-parameters`,
            {
                family: "postgres16",
                parameters: [{
                    name: "rds.force_ssl",
                    value: "1",
                }],
                tags,
            },
            childOptions,
        );

        this.database = new aws.rds.Instance(
            `${name}-postgres`,
            {
                engine: "postgres",
                engineVersion: "16",
                instanceClass:
                    args.environment === "prod"
                        ? "db.t3.medium"
                        : "db.t3.micro",

                allocatedStorage: args.environment === "prod" ? 50 : 20,
                maxAllocatedStorage: args.environment === "prod" ? 200 : 50,
                storageType: "gp3",
                storageEncrypted: true,

                dbName: args.databaseName,
                username: args.databaseUsername,
                password: args.databasePassword,
                port: 5432,

                dbSubnetGroupName: dbSubnetGroup.name,
                parameterGroupName: dbParameterGroup.name,
                vpcSecurityGroupIds: args.databaseSecurityGroupIds,

                multiAz: args.environment === "prod",
                publiclyAccessible: false,
                deletionProtection: true,
                backupRetentionPeriod: args.environment === "prod" ? 14 : 7,
                backupWindow: "03:00-04:00",
                maintenanceWindow: "sun:04:00-sun:05:00",
                autoMinorVersionUpgrade: true,
                copyTagsToSnapshot: true,

                // If deletion protection is explicitly disabled before destroy,
                // retain a final database snapshot.
                skipFinalSnapshot: false,
                finalSnapshotIdentifier: `${name}-${args.environment}-final`,
                applyImmediately: args.environment === "dev",

                tags,
            },
            {
                parent: this,
                additionalSecretOutputs: ["password"],
            },
        );

        /*
         * IAM role for an EKS service account using IRSA.
         */
        const oidcConditionKey = pulumi
            .output(args.serviceAccount.oidcIssuerUrl)
            .apply(url => url.replace(/^https:\/\//, ""));

        const serviceAccountSubject = pulumi.interpolate`system:serviceaccount:${args.serviceAccount.namespace}:${args.serviceAccount.name}`;

        this.serviceAccountRole = new aws.iam.Role(
            `${name}-service-account-role`,
            {
                assumeRolePolicy: pulumi
                    .all([
                        args.serviceAccount.oidcProviderArn,
                        oidcConditionKey,
                        serviceAccountSubject,
                    ])
                    .apply(([providerArn, conditionKey, subject]) =>
                        JSON.stringify({
                            Version: "2012-10-17",
                            Statement: [{
                                Effect: "Allow",
                                Principal: {
                                    Federated: providerArn,
                                },
                                Action: "sts:AssumeRoleWithWebIdentity",
                                Condition: {
                                    StringEquals: {
                                        [`${conditionKey}:aud`]: "sts.amazonaws.com",
                                        [`${conditionKey}:sub`]: subject,
                                    },
                                },
                            }],
                        }),
                    ),
                tags,
            },
            childOptions,
        );

        const applicationBucketPolicy = aws.iam.getPolicyDocumentOutput({
            statements: [
                {
                    sid: "ListApplicationBucket",
                    effect: "Allow",
                    actions: ["s3:ListBucket"],
                    resources: [this.bucket.arn],
                },
                {
                    sid: "ReadWriteApplicationObjects",
                    effect: "Allow",
                    actions: [
                        "s3:GetObject",
                        "s3:GetObjectVersion",
                        "s3:PutObject",
                        "s3:DeleteObject",
                    ],
                    resources: [
                        pulumi.interpolate`${this.bucket.arn}/*`,
                    ],
                },
            ],
        }).json;

        new aws.iam.RolePolicy(
            `${name}-service-account-bucket-policy`,
            {
                role: this.serviceAccountRole.id,
                policy: applicationBucketPolicy,
            },
            childOptions,
        );

        /*
         * Dev additionally receives a programmatic IAM user. Prod only uses
         * the least-privilege OIDC-backed role.
         */
        if (args.environment === "dev") {
            this.developmentUser = new aws.iam.User(
                `${name}-development-user`,
                {
                    tags,
                },
                childOptions,
            );

            new aws.iam.UserPolicy(
                `${name}-development-user-policy`,
                {
                    user: this.developmentUser.name,
                    policy: applicationBucketPolicy,
                },
                childOptions,
            );

            this.developmentAccessKey = new aws.iam.AccessKey(
                `${name}-development-access-key`,
                {
                    user: this.developmentUser.name,
                },
                childOptions,
            );

            this.developmentAccessKeyId = this.developmentAccessKey.id;
            this.developmentSecretAccessKey =
                pulumi.secret(this.developmentAccessKey.secret);
        }

        this.bucketName = this.bucket.bucket;
        this.bucketArn = this.bucket.arn;
        this.databaseEndpoint = this.database.endpoint;
        this.serviceAccountRoleArn = this.serviceAccountRole.arn;

        this.databaseConnectionString = pulumi.secret(
            pulumi
                .all([
                    args.databaseUsername,
                    args.databasePassword,
                    this.database.address,
                    this.database.port,
                    args.databaseName,
                ])
                .apply(([username, password, host, port, database]) => {
                    const encodedUser = encodeURIComponent(username);
                    const encodedPassword = encodeURIComponent(password);

                    return `postgresql://${encodedUser}:${encodedPassword}@${host}:${port}/${database}?sslmode=require`;
                }),
        );

        this.registerOutputs({
            bucketName: this.bucketName,
            bucketArn: this.bucketArn,
            replicationBucketName: this.replicationBucket?.bucket,
            databaseEndpoint: this.databaseEndpoint,
            databaseConnectionString: this.databaseConnectionString,
            serviceAccountRoleArn: this.serviceAccountRoleArn,
            developmentAccessKeyId: this.developmentAccessKeyId,
            developmentSecretAccessKey: this.developmentSecretAccessKey,
        });
    }
}
```

## `index.ts`

This example expects networking and EKS OIDC information to come from configuration. In a larger stack, these values would normally be outputs from VPC and EKS components.

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { ApplicationData } from "./components/applicationData";

const config = new pulumi.Config();

const environment = config.require("environment");
if (environment !== "dev" && environment !== "prod") {
    throw new Error("environment must be either dev or prod");
}

const region = config.require("region");
const dbPassword = config.requireSecret("dbPassword");

const primaryProvider = new aws.Provider("primary", {
    region: region as aws.Region,
});

const replicationProvider = environment === "prod"
    ? new aws.Provider("replication", {
          region: "us-west-2",
      })
    : undefined;

const data = new ApplicationData(
    "webapp",
    {
        environment,

        databaseSubnetIds: config.requireObject<string[]>("databaseSubnetIds"),
        databaseSecurityGroupIds:
            config.requireObject<string[]>("databaseSecurityGroupIds"),

        databaseName: config.get("databaseName") ?? "webapp",
        databaseUsername: config.get("databaseUsername") ?? "webapp_admin",
        databasePassword: dbPassword,

        serviceAccount: {
            namespace: config.get("serviceAccountNamespace") ?? "webapp",
            name: config.get("serviceAccountName") ?? "webapp",
            oidcProviderArn: config.require("oidcProviderArn"),
            oidcIssuerUrl: config.require("oidcIssuerUrl"),
        },

        replicationProvider,

        tags: {
            Application: "webapp",
            Environment: environment,
        },
    },
    {
        provider: primaryProvider,
    },
);

export const assetsBucketName = data.bucketName;
export const databaseEndpoint = data.databaseEndpoint;
export const databaseConnectionString = data.databaseConnectionString;
export const serviceAccountRoleArn = data.serviceAccountRoleArn;

// Present only in dev. Both are handled as sensitive credentials.
export const developmentAccessKeyId = data.developmentAccessKeyId;
export const developmentSecretAccessKey = data.developmentSecretAccessKey;
```

## `Pulumi.yaml`

```yaml
name: webapp-infrastructure
runtime:
  name: nodejs
  options:
    typescript: true
description: Web application data and IAM infrastructure
```

## `Pulumi.dev.yaml`

Do not place the real password directly in this file. Set it with `pulumi config set --secret`.

```yaml
config:
  webapp-infrastructure:environment: dev
  webapp-infrastructure:region: us-east-1
  webapp-infrastructure:databaseName: webapp
  webapp-infrastructure:databaseUsername: webapp_admin

  webapp-infrastructure:databaseSubnetIds:
    - subnet-DEVPRIVATE1
    - subnet-DEVPRIVATE2

  webapp-infrastructure:databaseSecurityGroupIds:
    - sg-DEVDB

  webapp-infrastructure:serviceAccountNamespace: webapp
  webapp-infrastructure:serviceAccountName: webapp
  webapp-infrastructure:oidcProviderArn: arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/DEVEXAMPLE
  webapp-infrastructure:oidcIssuerUrl: https://oidc.eks.us-east-1.amazonaws.com/id/DEVEXAMPLE
```

